/// Marks every episode in `episodes` whose `seasonNumber` matches as watched, then reschedules
/// pending episode notifications so any alerts for the marked episodes are cancelled or updated.
///
/// - Parameters:
///   - mediaId: The TMDB show ID.
///   - seasonNumber: Episodes whose `seasonNumber` differs are ignored.
///   - episodes: Candidate episodes; duplicates are filtered by `markEpisodeWatched`.
///   - context: SwiftData context used for inserts and the explicit save before notification rescheduling.
func markAllEpisodesOfSeasonWatched(
    mediaId: Int,
    seasonNumber: Int,
    episodes: [Episode],
    context: ModelContext
) async {
    for episode in episodes where episode.seasonNumber == seasonNumber {
        markEpisodeWatched(
            mediaId: mediaId,
            episodeId: episode.id,
            seasonNumber: episode.seasonNumber,
            episodeNumber: episode.episodeNumber,
            context: context
        )
    }

    try? context.save()

    let items = fetchAllWatchlistItems(context: context)
    await NotificationManager.shared.rescheduleEpisodeNotifications(items: items)
}

